import ws from 'k6/ws';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';
import { Counter } from 'k6/metrics';

const wsMessages = new Counter('ws_messages_received');

// 1. Load the JWTs generated by the LoadTestSeeder
const data = JSON.parse(open('./k6-data.json'));
const users = data.jwts;

export const options = {
  stages: [
    { duration: '30s', target: 50 },  // Slowly ramp to 50 concurrent connections
    { duration: '1m', target: 50 },   // Hold at 50
    { duration: '15s', target: 0 },    // Disconnect everyone
  ],
};

export default function () {
  const url = 'ws://localhost:80/ws';
  const randomUserJwt = users[Math.floor(Math.random() * users.length)];

  const params = { tags: { my_tag: 'websocket' } };

  const res = ws.connect(url, params, function (socket) {
    socket.on('open', function () {
      // Send STOMP CONNECT frame
      socket.send(
        `CONNECT\naccept-version:1.1,1.0\nheart-beat:10000,10000\nAuthorization:Bearer ${randomUserJwt}\n\n\0`
      );
    });

    socket.on('message', function (message) {
      if (message.includes('CONNECTED')) {
        // Upon successful connection, subscribe to the global auction topic
        socket.send(`SUBSCRIBE\nid:sub-0\ndestination:/topic/auctions\n\n\0`);
        
        // Subscribe to personal wallet queue
        socket.send(`SUBSCRIBE\nid:sub-1\ndestination:/user/queue/wallet\n\n\0`);
      } else if (message.includes('MESSAGE')) {
        // Count every time we receive a live update broadcast
        wsMessages.add(1);
      }
    });

    socket.on('close', function () {
      // Do nothing
    });

    socket.on('error', function (e) {
      if (e.error() != "websocket: close sent") {
        console.log('An unexpected error occurred: ', e.error());
      }
    });

    // Hold the connection open for 15 seconds to receive real-time broadcasts
    socket.setTimeout(function () {
      socket.close();
    }, 15000);
  });

  check(res, { 'Connected successfully': (r) => r && r.status === 101 });
}
